import { Component } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule } from '@angular/router';
import { AuthService } from '../../core/services/auth.service';

@Component({
  selector: 'app-admin-layout',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div class="admin-layout">
      <aside class="admin-sidebar">
        <div class="sidebar-header">
          <span class="material-icons">beach_access</span> Admin Panel
        </div>
        <ul class="sidebar-menu">
          <li><a routerLink="/admin/dashboard" routerLinkActive="active"><span class="material-icons">dashboard</span> Dashboard</a></li>
          <li><a routerLink="/admin/destinations" routerLinkActive="active"><span class="material-icons">place</span> Điểm đến</a></li>
          <li><a routerLink="/admin/tours" routerLinkActive="active"><span class="material-icons">tour</span> Tour</a></li>
          <li><a routerLink="/admin/articles" routerLinkActive="active"><span class="material-icons">article</span> Bài viết</a></li>
          <li><a routerLink="/admin/categories" routerLinkActive="active"><span class="material-icons">category</span> Danh mục</a></li>
          <li><a routerLink="/admin/users" routerLinkActive="active"><span class="material-icons">people</span> Người dùng</a></li>
          <li><a routerLink="/admin/reviews" routerLinkActive="active"><span class="material-icons">star</span> Đánh giá</a></li>
          <li><a routerLink="/admin/inquiries" routerLinkActive="active"><span class="material-icons">support_agent</span> Yêu cầu tư vấn</a></li>
          <li><a routerLink="/" routerLinkActive="active"><span class="material-icons">home</span> Về website</a></li>
          <li><a (click)="logout()" style="cursor:pointer;"><span class="material-icons">logout</span> Đăng xuất</a></li>
        </ul>
      </aside>
      <div class="admin-main">
        <header class="admin-header">
          <h2>Quản trị Du Lịch Quảng Bá</h2>
          <div class="header-actions">
            <span>Xin chào, {{ auth.user()?.fullName }}</span>
          </div>
        </header>
        <div class="admin-content">
          <router-outlet></router-outlet>
        </div>
      </div>
    </div>
  `,
  styles: [`
    .sidebar-header { display: flex; align-items: center; gap: 0.5rem; }
  `]
})
export class AdminLayoutComponent {
  constructor(public auth: AuthService) {}
  logout() { this.auth.logout(); }
}
